('assessment-equipment','Person-specific equipment assessment','Suitability, compatibility, training, maintenance and contingency.',215,'[{"key":"equipmentDetails","label":"Equipment, purpose and person-specific suitability","type":"textarea","required":true},{"key":"maintenanceContingency","label":"Training, checks, maintenance and contingency","type":"textarea","required":true}]'::jsonb),
('assessment-end-of-life','End-of-life wishes and coordination assessment','Wishes, capacity, representation, advance planning and professional coordination.',216,'[{"key":"wishesPriorities","label":"Person’s wishes, priorities and what matters now","type":"textarea","required":true},{"key":"advancePlanning","label":"Advance decisions, DNACPR location and professional coordination","type":"textarea"}]'::jsonb),
