), common AS (
 SELECT '[{"key":"initialAssessmentReference","label":"Initial assessment reference","type":"text","required":true},{"key":"consentRecordReference","label":"Consent and authority record reference","type":"text","required":true},{"key":"personInvolvement","label":"How was the person involved and supported?","type":"textarea","required":true},{"key":"assessorCompetence","label":"Assessor role, competence and professional input","type":"textarea","required":true},{"key":"assessmentFindings","label":"Assessment findings and evidence considered","type":"textarea","required":true},{"key":"controlsPlan","label":"Agreed controls, support plan and responsible people","type":"textarea","required":true},{"key":"escalation","label":"Escalation or referral required","type":"textarea"},{"key":"reviewTriggers","label":"Review triggers","type":"textarea","required":true},{"key":"nextReviewDate","label":"Next review date","type":"date","required":true}]'::jsonb fields
), rows AS (
 SELECT key,name,description,sort_order,(common.fields || specialist.extra) field_schema FROM specialist CROSS JOIN common
 UNION ALL
 SELECT 'assessment-initial-needs','Initial needs and suitability assessment','First assessment of needs, preferences, outcomes, urgent risks and whether the service can safely meet them.',200,'[{"key":"personReference","label":"Person’s secure internal reference","type":"text","required":true},{"key":"referralSource","label":"Referral source and commissioner reference","type":"text"},{"key":"personInvolvement","label":"How was the person involved and supported?","type":"textarea","required":true},{"key":"representativesProfessionals","label":"Representatives and professionals involved","type":"textarea"},{"key":"needsPreferences","label":"Physical, mental, emotional, social, cultural, spiritual and communication needs","type":"textarea","required":true},{"key":"desiredOutcomes","label":"Outcomes and daily routines important to the person","type":"textarea","required":true},{"key":"urgentRisks","label":"Immediate risks and interim controls","type":"textarea","required":true},{"key":"serviceCompatibility","label":"Can the service safely meet the assessed needs?","type":"select","required":true,"options":["Yes","Yes with conditions","Further information required","No"]},{"key":"conditionsGaps","label":"Conditions, information gaps or reasons service is unsuitable","type":"textarea"},{"key":"consentRequired","label":"Consent and authority checklist required before specialist assessments","type":"boolean","required":true},{"key":"assessorDecision","label":"Assessor decision and management approval","type":"textarea","required":true},{"key":"nextReviewDate","label":"Next review date","type":"date","required":true}]'::jsonb
 UNION ALL
 SELECT 'assessment-consent-authority','Consent and authority checklist','Separate decision-specific consent and legal-authority record completed before specialist assessments.',201,'[{"key":"personReference","label":"Person’s secure internal reference","type":"text","required":true},{"key":"initialAssessmentReference","label":"Initial assessment reference","type":"text","required":true},{"key":"informationSupport","label":"Accessible information and decision-making support provided","type":"textarea","required":true},{"key":"careConsent","label":"Consent to care and personal support","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"medicinesConsent","label":"Consent to medicines support","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"healthcareConsent","label":"Consent to delegated healthcare tasks","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"informationSharingConsent","label":"Routine information-sharing choice","type":"select","required":true,"options":["Consented","Declined","Not applicable","Other lawful basis recorded","Capacity assessment required"]},{"key":"photoConsent","label":"Photograph or video choice","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"accessConsent","label":"Home, key-safe and access arrangements","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"moneyConsent","label":"Money, shopping or property support","type":"select","required":true,"options":["Consented","Declined","Not applicable","Capacity assessment required","Lawful representative decision"]},{"key":"representativeConsent","label":"Family, advocate or representative involvement","type":"select","required":true,"options":["Consented","Declined","Not applicable","Legal authority confirmed","Capacity assessment required"]},{"key":"authorityEvidence","label":"LPA, deputyship, advance decision or other authority evidence","type":"textarea"},{"key":"restrictionsRefusals","label":"Refusals, limits, conditions and withdrawal arrangements","type":"textarea","required":true},{"key":"capacityActions","label":"Decision-specific capacity or best-interest actions required","type":"textarea"},{"key":"assessorConfirmation","label":"Assessor confirmation and evidence checked","type":"textarea","required":true},{"key":"nextReviewDate","label":"Next review date or review trigger date","type":"date","required":true}]'::jsonb
)
INSERT INTO "RegisterDefinition" (id,"organisationId",key,name,description,"fieldSchema","isPublished","sortOrder","createdAt","updatedAt")
SELECT md5('register-definition:'||key)::uuid,NULL,key,name,description,field_schema,true,sort_order,NOW(),NOW() FROM rows
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,"fieldSchema"=EXCLUDED."fieldSchema","isPublished"=true,"sortOrder"=EXCLUDED."sortOrder","updatedAt"=NOW();
